using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var bingKey = Environment.GetEnvironmentVariable("BING_SEARCH_KEY"); // optional

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient chatClient = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Shared notebook for the note-taking tool ---
var notebook = new Notebook();

// --- Tools ---
var searchTool = AIFunctionFactory.Create(
    (string query) => SearchWebAsync(query, bingKey),
    "search_web",
    "Searches the web for the given query and returns a list of result snippets.");

var addNoteTool = AIFunctionFactory.Create(
    ([Description("A concise note capturing a key finding")] string note) =>
    {
        notebook.Add(note);
        return $"Note #{notebook.Count} saved.";
    },
    "add_note",
    "Saves a research note to the notebook for later summarization.");

var readNotesTool = AIFunctionFactory.Create(
    () => notebook.Count == 0
        ? "Notebook is empty."
        : string.Join("\n", notebook.Notes.Select((n, i) => $"[{i + 1}] {n}")),
    "read_notes",
    "Returns all research notes collected so far.");

// --- Agent loop ---
Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine("  Research Agent  (type 'exit' to quit)");
Console.WriteLine("═══════════════════════════════════════");

var systemPrompt = """
    You are a research agent. When the user provides a topic:
    1. Use the search_web tool to find relevant information (make several varied searches).
    2. Use the add_note tool to record every important finding as a short note.
    3. Use read_notes to review what you have collected.
    4. After gathering enough information, produce a well-structured summary with references.
    Always search at least twice with different queries before summarizing.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt)
};

var options = new ChatOptions
{
    Tools = [searchTool, addNoteTool, readNotesTool]
};

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("\nYou> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();
    history.Add(new(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.Write("\nAgent researching");

    var response = await chatClient.GetResponseAsync(history, options);

    // Append assistant response to history
    foreach (var msg in response.Messages)
        history.Add(msg);

    Console.ResetColor();
    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine("\n\nAgent>\n");
    Console.ResetColor();

    var answer = response.Messages
        .Where(m => m.Role == ChatRole.Assistant)
        .SelectMany(m => m.Contents.OfType<TextContent>())
        .LastOrDefault()?.Text ?? "(no response)";
    Console.WriteLine(answer);
}

Console.WriteLine("\nGoodbye!");
return;

// --- Web search implementation ---
static async Task<string> SearchWebAsync(string query, string? bingKey)
{
    Console.Write(".");
    if (!string.IsNullOrEmpty(bingKey))
    {
        return await BingSearchAsync(query, bingKey);
    }

    // Fallback: use a free search API
    return await FallbackSearchAsync(query);
}

static async Task<string> BingSearchAsync(string query, string apiKey)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.Add("Ocp-Apim-Subscription-Key", apiKey);
    var url = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
    var json = await http.GetFromJsonAsync<JsonElement>(url);

    var results = json.GetProperty("webPages").GetProperty("value")
        .EnumerateArray()
        .Select(v => $"• {v.GetProperty("name").GetString()}\n  {v.GetProperty("snippet").GetString()}\n  {v.GetProperty("url").GetString()}")
        .ToList();

    return results.Count == 0 ? "No results found." : string.Join("\n\n", results);
}

static async Task<string> FallbackSearchAsync(string query)
{
    try
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_redirect=1";
        var json = await http.GetFromJsonAsync<JsonElement>(url);

        var results = new List<string>();

        if (json.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } absText)
            results.Add($"• Summary: {absText}\n  Source: {json.GetProperty("AbstractURL").GetString()}");

        if (json.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var topic in topics.EnumerateArray().Take(5))
            {
                if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                {
                    var topicUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : "";
                    results.Add($"• {t}\n  {topicUrl}");
                }
            }
        }

        return results.Count == 0
            ? $"No structured results from DuckDuckGo for '{query}'. Try a different search query."
            : string.Join("\n\n", results);
    }
    catch (Exception ex)
    {
        return $"Search failed ({ex.Message}). Try a different query.";
    }
}

